package com.intellij.openapi.util;
public final class NlsActions {
  private NlsActions() {}
  @java.lang.annotation.Retention(java.lang.annotation.RetentionPolicy.CLASS)
  @java.lang.annotation.Target({java.lang.annotation.ElementType.TYPE_USE, java.lang.annotation.ElementType.PARAMETER, java.lang.annotation.ElementType.METHOD, java.lang.annotation.ElementType.FIELD})
  public @interface ActionText {}
}
